/*
 * Graphite clean navigation.
 *
 * Runs in three places (skin.json "Navigation" option):
 *
 * - Main window: Steam opens a dropdown whenever the pointer touches the
 *   Store / Library / Community tabs. Those dropdowns only repeat what each
 *   section's own page navigation already offers, so they are switched off
 *   here. Clicking a tab still navigates as usual.
 *   The bottom bar is hidden too: Downloads and Friends & Chat become two
 *   icon buttons next to the notifications. They simply click Steam's own
 *   (hidden) buttons, and the download icon mirrors the download progress.
 * - steamcommunity.com: the community has no navigation of its own inside
 *   the client (it lived in those dropdowns), so a slim sub-navigation is
 *   added on top of every community page: Home, Discussions, Workshop,
 *   Market, Broadcasts and your own Activity, Profile, Friends, Groups,
 *   Content, Badges and Inventory.
 * - store.steampowered.com: the store keeps its own navigation; only the
 *   Points Shop link (which was only reachable through the dropdown) is
 *   added next to the wishlist.
 *
 * Fully local; no network access.
 */
(() => {
	if (window.__graphiteNav) return;
	window.__graphiteNav = true;

	const host = location.hostname;
	const ready = fn => (document.readyState === 'loading' ? document.addEventListener('DOMContentLoaded', fn, { once: true }) : fn());

	/* --- Main window: no hover dropdowns on the tabs ------------------------ */
	if (host !== 'steamcommunity.com' && host !== 'store.steampowered.com') {
		// React derives onMouseEnter / onMouseLeave from mouseover / mouseout
		// (using relatedTarget), so swallowing every such event that starts or
		// ends on a tab keeps the dropdown closed. CSS :hover is unaffected.
		const TAB = '._7AlhCx3XGzBeIrQaCneUD';
		const inTab = n => !!(n && n.nodeType === 1 && n.closest(TAB));
		const stop = e => {
			if (inTab(e.target) || inTab(e.relatedTarget)) e.stopImmediatePropagation();
		};
		for (const type of ['mouseover', 'mouseout', 'pointerover', 'pointerout']) {
			window.addEventListener(type, stop, true);
		}

		// Downloads / Friends & Chat in the title bar
		const CTRL = '._3cykd-VfN_xBxf3Qxriccm';
		const DL = '._2EQ7ghgqIdjKv9jsQC0Zq9';
		const FR = '._1TdaAqMFadi0UTqilrkelR';
		const PB = '.wi0pDywRgOCxhG7OqQNaA';
		const PCT = '._1-TLiuTZBQNz2fvBGj6aq-';
		const icon = d => `<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${d}</svg>`;
		const ICON_DL = icon('<path d="M12 4v11"/><path d="m7 10 5 5 5-5"/><path d="M5 20h14"/>');
		const ICON_FR = icon('<circle cx="9" cy="8" r="3.5"/><path d="M2.5 20a6.5 6.5 0 0 1 13 0"/><path d="M16 4.5a3.5 3.5 0 0 1 0 7"/><path d="M18.5 14a6.5 6.5 0 0 1 3 6"/>');
		// click the innermost first element so the event bubbles through every
		// element that might carry Steam's handler
		const press = el => {
			if (!el) return;
			let t = el;
			while (t.firstElementChild && !(t.firstElementChild instanceof SVGElement)) t = t.firstElementChild;
			t.click();
		};
		const mount = () => {
			const ctrl = document.querySelector(CTRL);
			if (!ctrl || ctrl.querySelector('.gr-quick')) return;
			const wrap = document.createElement('div');
			wrap.className = 'gr-quick';
			wrap.innerHTML = `<div class="gr-qbtn gr-q-dl">${ICON_DL}<span class="gr-q-bar"><i></i></span></div><div class="gr-qbtn gr-q-fr">${ICON_FR}</div>`;
			wrap.querySelector('.gr-q-dl').addEventListener('click', () => press(document.querySelector(DL)));
			wrap.querySelector('.gr-q-fr').addEventListener('click', () => { const f = document.querySelector(FR); if (f) f.click(); });
			ctrl.prepend(wrap);
		};
		// (innerText is empty for the hidden bar, so join the leaf texts)
		const text = el => [...el.querySelectorAll('*')]
			.filter(e => !e.children.length && !(e instanceof SVGElement))
			.map(e => e.textContent.trim()).filter(Boolean).join(' · ');
		const update = () => {
			mount();
			const btn = document.querySelector('.gr-q-dl');
			const dl = document.querySelector(DL);
			if (!btn || !dl) return;
			const bar = dl.querySelector(PB);
			let pct = null;
			const label = dl.querySelector(PCT);
			if (label && /\d/.test(label.textContent)) pct = parseFloat(label.textContent.replace(',', '.'));
			else if (bar && bar.parentElement) {
				const w = bar.parentElement.getBoundingClientRect().width;
				if (w) pct = (bar.getBoundingClientRect().width / w) * 100;
			}
			const active = pct !== null && !Number.isNaN(pct);
			btn.classList.toggle('gr-active', active);
			btn.style.setProperty('--gr-progress', active ? Math.max(0, Math.min(100, pct)) + '%' : '0%');
			btn.title = text(dl);
			const fr = document.querySelector('.gr-q-fr');
			const f = document.querySelector(FR);
			if (fr && f) fr.title = text(f);
		};
		update();
		setInterval(update, 1000);
		return;
	}

	// Graphite 2.0: the client's side column is the store / community
	// navigation, so no sub-navigation or extra links inside the page
	if (window.__graphiteShellPage) return;

	/* --- Labels ------------------------------------------------------------ */
	const L = {
		en: ['Home', 'Discussions', 'Workshop', 'Market', 'Broadcasts', 'Activity', 'Profile', 'Friends', 'Groups', 'Content', 'Badges', 'Inventory', 'Points Shop'],
		de: ['Startseite', 'Diskussionen', 'Workshop', 'Markt', 'Übertragungen', 'Aktivität', 'Profil', 'Freunde', 'Gruppen', 'Inhalte', 'Abzeichen', 'Inventar', 'Punkteshop'],
		fr: ['Accueil', 'Discussions', 'Workshop', 'Marché', 'Diffusions', 'Activité', 'Profil', 'Amis', 'Groupes', 'Contenu', 'Badges', 'Inventaire', 'Boutique des points'],
		es: ['Inicio', 'Discusiones', 'Workshop', 'Mercado', 'Retransmisiones', 'Actividad', 'Perfil', 'Amigos', 'Grupos', 'Contenido', 'Insignias', 'Inventario', 'Tienda de puntos'],
	};
	const KEYS = ['home', 'discussions', 'workshop', 'market', 'broadcasts', 'activity', 'profile', 'friends', 'groups', 'content', 'badges', 'inventory', 'points'];
	const lang = (document.documentElement.lang || 'en').slice(0, 2).toLowerCase();
	const t = key => (L[lang] || L.en)[KEYS.indexOf(key)];

	const css = `
		.gr-subnav {
			position: relative; z-index: 50;
			background: var(--gr-bg, #0b0b0d);
			border-bottom: 1px solid var(--gr-border, #232328);
			font-family: var(--gr-font, inherit);
		}
		.gr-subnav-inner {
			box-sizing: border-box;
			max-width: 1232px; height: 48px; margin: 0 auto; padding: 0 16px;
			display: flex; align-items: center; gap: 2px;
			overflow-x: auto; scrollbar-width: none;
		}
		.gr-subnav-inner::-webkit-scrollbar { display: none; }
		/* line the link text up with the store navigation and page content */
		.gr-subnav-inner > a:first-child { margin-left: -12px; }
		.gr-subnav-inner > a:last-child { margin-right: -12px; }
		.gr-subnav a {
			position: relative; flex: none;
			display: inline-flex; align-items: center; height: 32px; padding: 0 12px;
			border-radius: var(--gr-radius-sm, 6px);
			color: var(--gr-text-2, #a1a1ab) !important;
			font-size: 14px; font-weight: 500; line-height: 1; letter-spacing: 0;
			text-decoration: none !important; white-space: nowrap;
			transition: background 120ms ease, color 120ms ease;
		}
		.gr-subnav a:hover { background: var(--gr-hover, rgba(255,255,255,.06)); color: var(--gr-text, #ececf0) !important; }
		.gr-subnav a.gr-active { color: var(--gr-text, #ececf0) !important; }
		.gr-subnav a.gr-active::after {
			content: ""; position: absolute; left: 12px; right: 12px; bottom: -8px;
			height: 2px; border-radius: 2px; background: var(--gr-accent, #8fa8ff);
		}
		.gr-subnav-sep { flex: none; width: 1px; height: 18px; margin: 0 10px; background: var(--gr-border, #232328); }
		.gr-subnav-spacer { flex: 1 1 auto; }
		.gr-points-link {
			display: inline-flex; align-items: center; height: 100%; padding: 0 12px;
			color: var(--gr-text, #ececf0) !important; font-size: 14px; font-weight: 500;
			text-decoration: none !important; white-space: nowrap;
			transition: opacity 120ms ease;
		}
		.gr-points-link:hover { opacity: .75; }
	`;
	const addStyle = () => {
		const s = document.createElement('style');
		s.dataset.graphiteNav = '';
		s.textContent = css;
		(document.head || document.documentElement).appendChild(s);
	};

	/* --- Store: Points Shop next to the wishlist ---------------------------- */
	if (host === 'store.steampowered.com') {
		ready(() => {
			addStyle();
			const place = () => {
				if (document.querySelector('.gr-points-link')) return true;
				// the wishlist button of the store navigation: the first wishlist
				// link on the page that has an icon (star) and a label
				const wish = [...document.querySelectorAll('a[href*="/wishlist"]')]
					.find(a => a.querySelector('svg') && a.textContent.trim());
				if (!wish || !wish.parentElement) return false;
				const a = document.createElement('a');
				a.className = 'gr-points-link';
				a.href = 'https://store.steampowered.com/points/';
				a.textContent = t('points');
				wish.parentElement.insertBefore(a, wish);
				return true;
			};
				// The store header is rendered (and sometimes re-rendered) by React
			// after load, so keep checking cheaply whenever the DOM changes.
			let queued = false;
			new MutationObserver(() => {
				if (queued) return;
				queued = true;
				requestAnimationFrame(() => { queued = false; place(); });
			}).observe(document.body, { childList: true, subtree: true });
			place();
		});
		return;
	}

	/* --- Community: sub-navigation ----------------------------------------- */
	const steamId = () => {
		if (window.g_steamID) return String(window.g_steamID);
		const m = document.documentElement.innerHTML.match(/g_steamID\s*=\s*"(\d{17})"/);
		return m ? m[1] : null;
	};

	ready(() => {
		if (document.querySelector('.gr-subnav') || window.top !== window) return;
		const id = steamId();
		const path = location.pathname.replace(/\/+$/, '') || '/';
		const search = location.search;

		// Is this one of your own profile pages? Then return the sub path
		// (e.g. "/inventory"), otherwise null.
		// Profile links use /profiles/<id>, which Steam redirects to your custom
		// /id/<name> URL, so the name is remembered once a page reveals it.
		const ownSub = (() => {
			if (!id) return null;
			const m = path.match(/^\/(profiles|id)\/([^/]+)(\/.*)?$/);
			if (!m) return null;
			const w = window;
			const html = () => document.documentElement.innerHTML;
			const pageOwner = (w.g_rgProfileData && w.g_rgProfileData.steamid)
				|| (w.g_ActiveUser && w.g_ActiveUser.strSteamId)
				|| (html().match(/g_rgProfileData\s*=\s*\{[^}]*?"steamid":"(\d{17})"/) || [])[1];
			let vanity = null;
			try { vanity = localStorage.getItem('graphite-vanity'); } catch (e) { /* storage blocked */ }
			const own = m[2] === id || pageOwner === id || (m[1] === 'id' && m[2] === vanity);
			if (own && m[1] === 'id' && m[2] !== vanity) {
				try { localStorage.setItem('graphite-vanity', m[2]); } catch (e) { /* storage blocked */ }
			}
			return own ? (m[3] || '') : null;
		})();

		const C = 'https://steamcommunity.com';
		const me = id ? `${C}/profiles/${id}` : null;
		const groups = [
			[
				['home', `${C}/`, () => path === '/' && !/subsection=broadcasts/.test(search)],
				['discussions', `${C}/discussions/`, () => /^\/discussions/.test(path)],
				['workshop', `${C}/workshop/`, () => /^\/(workshop|sharedfiles)/.test(path)],
				['market', `${C}/market/`, () => /^\/market/.test(path)],
				['broadcasts', `${C}/?subsection=broadcasts`, () => /subsection=broadcasts/.test(search) || /^\/broadcast/.test(path)],
			],
			me ? [
				['activity', `${me}/home/`, () => ownSub === '/home'],
				['profile', `${me}/`, () => ownSub === ''],
				['friends', `${me}/friends/`, () => /^\/friends/.test(ownSub || '')],
				['groups', `${me}/groups/`, () => /^\/groups/.test(ownSub || '')],
				['content', `${me}/screenshots/`, () => /^\/(screenshots|images|videos|myworkshopfiles|recommended|reviews|guides)/.test(ownSub || '')],
				['badges', `${me}/badges/`, () => /^\/(badges|gamecards)/.test(ownSub || '')],
				['inventory', `${me}/inventory/`, () => /^\/inventory/.test(ownSub || '')],
			] : [],
		];

		addStyle();
		const nav = document.createElement('nav');
		nav.className = 'gr-subnav';
		const inner = document.createElement('div');
		inner.className = 'gr-subnav-inner';
		groups.forEach((items, gi) => {
			if (!items.length) return;
			if (gi > 0) {
				const sp = document.createElement('div');
				sp.className = 'gr-subnav-spacer';
				inner.appendChild(sp);
			}
			for (const [key, href, active] of items) {
				const a = document.createElement('a');
				a.href = href;
				a.textContent = t(key);
				if (active()) a.className = 'gr-active';
				inner.appendChild(a);
			}
		});
		nav.appendChild(inner);

		const anchor = document.querySelector('.responsive_page_template_content')
			|| document.querySelector('.responsive_page_content')
			|| document.body.firstElementChild;
		if (anchor && anchor.parentElement) anchor.parentElement.insertBefore(nav, anchor);
		else document.body.prepend(nav);
	});
})();
